// ==================================================

static void Show_Boot_Img(const uint8_t *img)
{
    // 1. 强制清空整个240x240屏幕，用黑色填充
    LCD_Fill_Buffer(0); 
    for (int y = 0; y < 240; y++) {
        for (int x = 0; x < 240; x++) {
            LCD_Set_Pixel(x, y, 0);
        }
    }

    // 2. 绘制图片
    for (int y = 0; y < 240; y++) {
        for (int x = 0; x < 240; x++) {
            uint8_t c = img[y * 240 + x];
            LCD_Set_Pixel(x, y, c);
        }
    }

    // 3. 刷新屏幕
    LCD_Refresh(&cfg0);
}

void Boot_Animation(void)
{
    // 循环播放 2 遍
    for(int loop = 0; loop < 3; loop++)
    {
        Show_Boot_Img(boot_img1);
        HAL_Delay(400);
        
        Show_Boot_Img(boot_img2);
        HAL_Delay(400);
        
        Show_Boot_Img(boot_img3);
        HAL_Delay(400);
        
        Show_Boot_Img(boot_img4);
        HAL_Delay(400);
    }
}